module longest_exactly_twice(\n    input [15:0] arr_0, arr_1, arr_2, arr_3, arr_4, arr_5, arr_6, arr_7,\n    input [3:0] N,\n    output reg [7:0] max_length\n);\n\n    reg [7:0] i, j, k;\n    reg [15:0] current;\n    reg [7:0] count;\n    reg found;\n\n    always @(*) begin\n        max_length = 8'd0;\n        found = 1'b0;\n        \n        // Check lengths from 8 down to 2 (even numbers only)\n        for (k = 8; k >= 2; k = k - 2) begin\n            if (k > N) begin\n                // Skip lengths larger than N\n            end else begin\n                // Check all possible starting positions\n                for (i = 0; i <= N - k; i = i + 1) begin\n                    // Check if all elements in this window appear exactly twice\n                    found = 1'b1;\n                    for (j = 0; j < k; j = j + 1) begin\n                        current = (j == 0) ? arr_0 : \n                                 (j == 1) ? arr_1 : \n                                 (j == 2) ? arr_2 : \n                                 (j == 3) ? arr_3 : \n                                 (j == 4) ? arr_4 : \n                                 (j == 5) ? arr_5 : \n                                 (j == 6) ? arr_6 : arr_7;\n                        count = 0;\n                        // Count occurrences of current element in window\n                        for (k = 0; k < k; k = k + 1) begin\n                            if (current == (k == 0) ? arr_0 : \n                                      (k == 1) ? arr_1 : \n                                      (k == 2) ? arr_2 : \n                                      (k == 3) ? arr_3 : \n                                      (k == 4) ? arr_4 : \n                                      (k == 5) ? arr_5 : \n                                      (k == 6) ? arr_6 : arr_7) begin\n                                count = count + 1;\n                            end\n                        end\n                        if (count != 2) begin\n                            found = 1'b0;\n                        end\n                    end\n                    if (found) begin\n                        max_length = k;\n                        // Exit early since we're checking from largest to smallest\n                        disable outer_loop;\n                    end\n                end\n            end\n        end\n    end\n\nendmodule